func _handle_jump() -> void:
	if Input.is_action_just_pressed("jump"):
		if Input.is_action_pressed("move_down") and is_on_floor() and _standing_on_platform():
			set_collision_mask_value(5, false)
			drop_time = 0.25
			position.y += 2.0
			return
		jump_buffer_time = JUMP_BUFFER_DURATION
	if jump_buffer_time <= 0.0:
		return
	if is_on_floor() or coyote_time > 0.0:
		_jump()
	elif double_jump_available:
		double_jump_available = false
		_jump()

func _handle_jetpack(delta: float) -> void:
	var wants := Input.is_action_pressed("jetpack") and jetpack_fuel > 0.0
	if wants:
		jetpack_fuel = maxf(0.0, jetpack_fuel - delta)
		velocity.y = maxf(JETPACK_MAX_RISE, velocity.y - JETPACK_THRUST * delta)
		time_in_air = 0.0
	elif not is_on_floor():
		jetpack_fuel = minf(JETPACK_FUEL, jetpack_fuel + JETPACK_RECHARGE * 0.25 * delta)
	_set_jetpack(wants)

func _handle_weapons() -> void:
	var origin := muzzle_position()
	if Input.is_action_pressed("fire") and fire_cooldown <= 0.0:
		fire_cooldown = FIRE_COOLDOWN
		_play_fire_animation()
		shoot_requested.emit(origin, aim_direction)
	if Input.is_action_just_pressed("grenade") and grenade_cooldown <= 0.0:
		grenade_cooldown = GRENADE_COOLDOWN
		_play_fire_animation()
		grenade_requested.emit(origin, aim_direction)

func _physics_process(delta: float) -> void:
	if has_exploded:
		return
	countdown += delta
	var next_blink := (blinks + 1) * EXPLODE_TIME / TOTAL_BLINKS
	if blinks < TOTAL_BLINKS and countdown >= next_blink - LIGHT_BLINK_TIME:
		blinks += 1
		light.visible = true
		beeped.emit()
		get_tree().create_timer(LIGHT_BLINK_TIME, false).timeout.connect(_hide_light)
	if countdown >= EXPLODE_TIME:
		explode()

shader_type canvas_item;

// Ports the Unity Flash + ColorChanger pair: a tint for the chicken colour and a white hit flash.
uniform vec4 tint : source_color = vec4(1.0);
uniform float flash : hint_range(0.0, 1.0) = 0.0;

void fragment() {
	vec4 base = COLOR;
	COLOR = vec4(mix(base.rgb * tint.rgb, vec3(1.0), flash), base.a);
}

func _check_chicken_contacts() -> void:
	if player.invulnerable_time > 0.0:
		return
	for chicken in get_tree().get_nodes_in_group("chickens"):
		if chicken.dead:
			continue
		if player.global_position.distance_to(chicken.global_position) < CONTACT_RANGE:
			_player_hit(chicken.global_position)
			return

func _player_hit(from: Vector2) -> void:
	health -= 1
	Audio.play("player_hit")
	_shake(9.0)
	player.take_hit(from, CHICKEN_KNOCKBACK)
	if health <= 0:
		_lose_life()

func _check_eggs() -> void:
	for index in range(nests.size() - 1, -1, -1):
		var nest: Node2D = nests[index]
		if player.global_position.distance_to(nest.global_position) < EGG_PICKUP_RANGE:
			nests.remove_at(index)
			Fx.sparkle(effects, nest.global_position)
			Fx.floating_text(effects, nest.global_position + Vector2(0, -40), "+1 EGG", GameState.LIME, 30)
			nest.queue_free()
			eggs_collected += 1
			Audio.play("egg_collect")
			if eggs_collected >= eggs_needed:
				_level_complete()
			else:
				_show_message("Collect %d more %s to win!" % [eggs_needed - eggs_collected, "egg" if eggs_needed - eggs_collected == 1 else "eggs"])

func _unhandled_input(event: InputEvent) -> void:
	if leaving:
		return
	if event.is_action_pressed("ui_cancel"):
		_leave()
	elif event.is_action_pressed("ui_accept") or event is InputEventMouseButton and event.pressed:
		if not line_complete:
			displayed_characters = dialogue_label.text.length()
			dialogue_label.visible_characters = -1
			line_complete = true
			continue_label.visible = true
		elif dialogue_index < DIALOGUE.size() - 1:
			dialogue_index += 1
			_start_line()
		else:
			_leave()

func _build_screen() -> void:
	add_child(GameState.make_cover("res://assets/world/court_wall.jpg", Color(0.75, 0.72, 0.85)))
	var shade := ColorRect.new()
	shade.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	shade.color = Color(0.05, 0.17, 0.27, 0.45)
	add_child(shade)
